const input=document.querySelector('#workflow-input'),button=document.querySelector('#run'),result=document.querySelector('#result'),required=JSON.parse(document.querySelector('#required').textContent),copy=JSON.parse(document.querySelector('#copy').textContent);function run(){let data;try{data=JSON.parse(input.value)}catch{result.className='result fail';result.textContent=copy.invalid+' JSON';return}const missing=required.filter(key=>data[key]===undefined||data[key]===null||data[key]==='');result.className='result '+(missing.length?'fail':'pass');result.textContent=missing.length?copy.invalid+' '+missing.join(', '):copy.valid}button.addEventListener('click',run);run();
